const { Buffer } = require('node:buffer')
const data = Buffer.alloc(4096)
let offset=0
for (char of table) {
  for (const row of char) {
    data.writeUInt8(parseInt(row, 2), offset)
    offset++
  }
}

async function write() {
  const fs = require('node:fs/promises')
  await fs.rm('./myfont.bin')
  const file = await fs.open('./myfont.bin', 'a')
  file.write(data)
  await file.close()
}
write()
